/**
 * FFI error type.
 */
public enum FfiError {

    
    
    case ProtectedPath(path: String
    )
    case BoundaryEscape(path: String, resolved: String
    )
    case PermissionDenied(path: String
    )
    case PathNotFound(path: String
    )
    case TrashFailed(path: String, reason: String
    )
    case ScanFailed(message: String
    )
    case CleanFailed(message: String
    )
    case ConfigError(message: String
    )
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeFFIError: FfiConverterRustBuffer {
    typealias SwiftType = FfiError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> FfiError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .ProtectedPath(
            path: try FfiConverterString.read(from: &buf)
            )
        case 2: return .BoundaryEscape(
            path: try FfiConverterString.read(from: &buf), 
            resolved: try FfiConverterString.read(from: &buf)
            )
        case 3: return .PermissionDenied(
            path: try FfiConverterString.read(from: &buf)
            )
        case 4: return .PathNotFound(
            path: try FfiConverterString.read(from: &buf)
            )
        case 5: return .TrashFailed(
            path: try FfiConverterString.read(from: &buf), 
            reason: try FfiConverterString.read(from: &buf)
            )
        case 6: return .ScanFailed(
            message: try FfiConverterString.read(from: &buf)
            )
        case 7: return .CleanFailed(
            message: try FfiConverterString.read(from: &buf)
            )
        case 8: return .ConfigError(
            message: try FfiConverterString.read(from: &buf)
            )

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: FfiError, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case let .ProtectedPath(path):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(path, into: &buf)
            
        
        case let .BoundaryEscape(path,resolved):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(path, into: &buf)
            FfiConverterString.write(resolved, into: &buf)
            
        
        case let .PermissionDenied(path):
            writeInt(&buf, Int32(3))
            FfiConverterString.write(path, into: &buf)
            
        
        case let .PathNotFound(path):
            writeInt(&buf, Int32(4))
            FfiConverterString.write(path, into: &buf)
            
        
        case let .TrashFailed(path,reason):
            writeInt(&buf, Int32(5))
            FfiConverterString.write(path, into: &buf)
            FfiConverterString.write(reason, into: &buf)
            
        
        case let .ScanFailed(message):
            writeInt(&buf, Int32(6))
            FfiConverterString.write(message, into: &buf)
            
        
        case let .CleanFailed(message):
            writeInt(&buf, Int32(7))
            FfiConverterString.write(message, into: &buf)
            
        
        case let .ConfigError(message):
            writeInt(&buf, Int32(8))
            FfiConverterString.write(message, into: &buf)
            
        }
    }
}


